#!/usr/bin/env node
/**
 * Safe, non-destructive roster seeder for Supabase PostgreSQL.
 * - Reads `src/data/roster.json` (generated by `npm run sync:roster`)
 * - Upserts rooms and students WITHOUT overwriting custom `nickname` values
 *   and WITHOUT deleting rooms/students added via the Admin web console.
 * - Bootstraps `app_security_config` with salted scrypt PIN hashes ONLY if empty.
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { createClient } from "@supabase/supabase-js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const projectRoot = path.resolve(__dirname, "..");

function loadDotEnvLocal() {
  const envPath = path.join(projectRoot, ".env.local");
  if (!fs.existsSync(envPath)) return;
  const content = fs.readFileSync(envPath, "utf8");
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    const eqIndex = line.indexOf("=");
    if (eqIndex <= 0) continue;
    const key = line.slice(0, eqIndex).trim();
    const val = line.slice(eqIndex + 1).trim().replace(/^["']|["']$/g, "");
    if (!process.env[key]) {
      process.env[key] = val;
    }
  }
}

function hashSecret(plain) {
  const salt = crypto.randomBytes(16).toString("hex");
  const derived = crypto.scryptSync(plain, salt, 64, { N: 16384, r: 8, p: 1 }).toString("hex");
  return `scrypt$${salt}$${derived}`;
}

async function main() {
  loadDotEnvLocal();

  const url = process.env.SUPABASE_URL;
  const secretKey = process.env.SUPABASE_SECRET_KEY;

  if (!url || !secretKey || secretKey.includes("replace_with")) {
    console.error(
      "[seed:supabase] Missing SUPABASE_URL or SUPABASE_SECRET_KEY in .env.local or environment."
    );
    process.exit(1);
  }

  const rosterPath = path.join(projectRoot, "src", "data", "roster.json");
  const roster = JSON.parse(fs.readFileSync(rosterPath, "utf8"));

  const supabase = createClient(url, secretKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  // 1. Upsert rooms (preserves existing timestamps/metadata safely)
  const roomRows = roster.rooms.map((room) => ({
    id: room.id,
    name: room.name,
    grade: room.grade,
    room_number: room.roomNumber,
    program: room.program ?? "",
    homeroom_teachers: room.homeroomTeachers ?? "",
    updated_at: new Date().toISOString(),
  }));

  const { error: roomError } = await supabase
    .from("rooms")
    .upsert(roomRows, { onConflict: "id" });

  if (roomError) {
    console.error("[seed:supabase] Failed to upsert rooms:", roomError.message);
    process.exit(1);
  }

  // 2. Fetch existing students so we NEVER overwrite custom nicknames
  const { data: existingStudents, error: fetchError } = await supabase
    .from("students")
    .select("id, nickname");

  if (fetchError) {
    console.error("[seed:supabase] Failed to read existing students:", fetchError.message);
    process.exit(1);
  }

  const existingNicknames = new Map(
    (existingStudents ?? []).map((row) => [row.id, row.nickname ?? null])
  );

  const studentRows = roster.students.map((student) => ({
    id: student.id,
    student_code: student.studentCode,
    room_id: student.roomId,
    seat_number: student.seatNumber,
    prefix: student.prefix ?? "",
    first_name: student.firstName,
    last_name: student.lastName ?? "",
    nickname: existingNicknames.get(student.id) ?? null,
    roster_note: student.rosterNote ?? null,
    updated_at: new Date().toISOString(),
  }));

  const { error: studentError } = await supabase
    .from("students")
    .upsert(studentRows, { onConflict: "id" });

  if (studentError) {
    console.error("[seed:supabase] Failed to upsert students:", studentError.message);
    process.exit(1);
  }

  // 3. Bootstrap app_security_config ONLY if not yet initialized
  const { data: existingConfig, error: configReadError } = await supabase
    .from("app_security_config")
    .select("id")
    .eq("id", 1)
    .maybeSingle();

  if (configReadError) {
    console.error("[seed:supabase] Failed to check security config:", configReadError.message);
    process.exit(1);
  }

  if (!existingConfig) {
    const staffPin = process.env.INITIAL_STAFF_PIN || "256900";
    const adminPin = process.env.INITIAL_ADMIN_PIN || "996900";
    if (staffPin === adminPin) {
      console.error("[seed:supabase] INITIAL_STAFF_PIN and INITIAL_ADMIN_PIN must be different.");
      process.exit(1);
    }

    const { error: configInsertError } = await supabase.from("app_security_config").insert({
      id: 1,
      staff_pin_hash: hashSecret(staffPin),
      admin_pin_hash: hashSecret(adminPin),
      updated_by: "seed_script",
    });

    if (configInsertError) {
      console.error("[seed:supabase] Failed to initialize security config:", configInsertError.message);
      process.exit(1);
    }
    console.log("[seed:supabase] Initialized salted scrypt PIN hashes in app_security_config.");
  }

  console.log(
    `[seed:supabase] Synced ${roomRows.length} rooms and ${studentRows.length} students (existing nicknames preserved).`
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
